import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    s = list(input_data[1])

    removed_count = 0
    current_char_code = ord('a') + 1

    while current_char_code <= ord('z'):
        target_char = chr(current_char_code)
        found_removal = False

        i = 0
        while i < len(s):
            if s[i] == target_char:
                left_ok = (i > 0 and s[i-1] == chr(current_char_code - 1))
                right_ok = (i < len(s) - 1 and s[i+1] == chr(current_char_code - 1))

                if left_ok or right_ok:
                    del s[i]
                    removed_count += 1
                    found_removal = True
                    continue
            i += 1

        if not found_removal:
            current_char_code += 1
        else:
            pass

    print(removed_count)

if __name__ == "__main__":
    solve()
